    private static final HttpClient CLIENT=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();
    private static Path root;private static AssessmentServer app;private static HttpServer http;private static ExecutorService workers;private static String base;private static KeyPair key;private static int checks;
    private record Session(String cookie,String csrf){}
    private record Response(int status,Map<String,Object> json,byte[] bytes,String cookie){}
    @SuppressWarnings("unchecked") private static Map<String,Object> obj(Object value){return (Map<String,Object>)value;}
    @SuppressWarnings("unchecked") private static List<Object> array(Object value){return (List<Object>)value;}
    private static void check(boolean condition,String message){checks++;if(!condition)throw new AssertionError(message);}
    private static String digest(byte[] data)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));}
    private static Path artifact(String name){return root.resolve("dist/agent-updates/"+DashboardVersion.VERSION+"/"+name);}
    private static void release(String jarVersion,Map<String,Object> overrides)throws Exception{
        Files.createDirectories(artifact("collector.jar").getParent());byte[] publicKey=key.getPublic().getEncoded();Files.write(root.resolve("dist/agent-update-public.der"),publicKey);
        Manifest metadata=new Manifest();metadata.getMainAttributes().putValue("Manifest-Version","1.0");metadata.getMainAttributes().putValue("Implementation-Version",jarVersion);ByteArrayOutputStream binary=new ByteArrayOutputStream();try(JarOutputStream jar=new JarOutputStream(binary,metadata)){jar.putNextEntry(new JarEntry("fixture.txt"));jar.write("signed harmless test data".getBytes());jar.closeEntry();}byte[] bytes=binary.toByteArray();Files.write(artifact("collector.jar"),bytes);
        Map<String,byte[]> assets=new LinkedHashMap<>();assets.put("update-public.der",publicKey);assets.put("update-service.sh","#!/bin/sh\nexit 0\n".getBytes());assets.put("lib/fixture.jar","stable fixture library".getBytes());Map<String,Object> required=new LinkedHashMap<>();for(var item:assets.entrySet())required.put(item.getKey(),digest(item.getValue()));
        try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(root.resolve("dist/assessment-collector.zip")))){for(var item:assets.entrySet()){zip.putNextEntry(new ZipEntry(item.getKey()));zip.write(item.getValue());zip.closeEntry();}}
        Map<String,Object> manifest=map("schema",1,"type","ASSESSMENT_AGENT_UPDATE_V1","version",DashboardVersion.VERSION,"format","collector-jar-v1","minUpdater",1,"sha256",digest(bytes),"bytes",bytes.length,"requiredFiles",required);manifest.putAll(overrides);byte[] content=Json.stringify(manifest).getBytes(java.nio.charset.StandardCharsets.UTF_8);Signature signer=Signature.getInstance("SHA256withRSA");signer.initSign(key.getPrivate());signer.update(content);Files.write(artifact("manifest.json"),content);Files.write(artifact("manifest.sig"),signer.sign());
    }
    private static Response request(String method,String path,Object body,Session session,String bearer)throws Exception{
        var builder=HttpRequest.newBuilder(URI.create(base+path)).timeout(Duration.ofSeconds(15));if(session!=null){builder.header("Cookie",session.cookie);if(session.csrf!=null)builder.header("X-CSRF-Token",session.csrf);}if(bearer!=null)builder.header("Authorization","Bearer "+bearer);if(body!=null)builder.header("Content-Type","application/json");var response=CLIENT.send(builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(Json.stringify(body))).build(),HttpResponse.BodyHandlers.ofByteArray());Map<String,Object> json=response.headers().firstValue("Content-Type").orElse("").startsWith("application/json")?obj(Json.parse(new String(response.body(),java.nio.charset.StandardCharsets.UTF_8))):Map.of();return new Response(response.statusCode(),json,response.body(),response.headers().firstValue("Set-Cookie").orElse("").split(";",2)[0]);
    }
    private static Response human(int status,String method,String path,Object body,Session session)throws Exception{Response response=request(method,path,body,session,null);check(response.status==status,path+" expected"+status+" got"+response.status+" "+response.json);return response;}
    private static Response agent(int status,String method,String path,Object body,String host)throws Exception{Response response=request(method,path,body,null,"token-"+host);check(response.status==status,path+" expected"+status+" got"+response.status+" "+response.json);return response;}
    private static Session session(Response response){return new Session(response.cookie,(String)response.json.get("csrfToken"));}
    private static void start()throws Exception{app=new AssessmentServer(root.toFile());http=HttpServer.create(new InetSocketAddress("127.0.0.1",0),32);workers=Executors.newFixedThreadPool(4);http.createContext("/",app);http.setExecutor(workers);http.start();base="http://127.0.0.1:"+http.getAddress().getPort();}
    private static void stop(){if(http!=null){http.stop(0);workers.shutdownNow();app.close();http=null;}}
    private static void host(String id,String version,String capability){app.store.transaction(()->{app.store.put("hosts",map("id",id,"hostname",id,"environmentId","env-fixture","collectorVersion",version,"updateCapability",capability,"uninstallCapability","uninstall-v1","lastSeen",AssessmentServer.now(),"coverage",map("status","complete")));app.store.put("identities",map("hostId",id,"status","active","agentToken","token-"+id,"installationId","installation-fixture-"+id));return null;});}
    private static Map<String,Object> order(List<String> ids,String key){return map("hostIds",ids,"targetVersion",DashboardVersion.VERSION,"requestKey",key,"expiresInMinutes",60);}
    private static Map<String,Object> created(Session admin,List<String> ids,String key)throws Exception{return human(200,"POST","/api/agent-updates",order(ids,key),admin).json;}
    private static String requestId(Map<String,Object> response,String host){for(Object value:array(response.get("requests"))){Map<String,Object> request=obj(value);if(host.equals(request.get("hostId")))return (String)request.get("id");}throw new AssertionError("Request missing for "+host);}
    private static Map<String,Object> claim(String host,String request)throws Exception{return agent(200,"POST","/api/agent/update/claim",map("hostId",host,"requestId",request),host).json;}
    private static Map<String,Object> action(String host,String capability)throws Exception{return agent(200,"GET","/api/agent/actions?hostId="+host+"&updateCapability="+capability,null,host).json;}
    private static void heartbeat(String host,String version)throws Exception{agent(200,"POST","/api/agent/heartbeat",map("hostId",host,"collectorVersion",version,"updateCapability","update-v1","uninstallCapability","uninstall-v1"),host);}
    private static void report(int status,String host,String request,String state,String version,String diagnostic)throws Exception{agent(status,"POST","/api/agent/update/report",map("hostId",host,"requestId",request,"status",state,"version",version,"diagnostic",diagnostic),host);}
    private static Map<String,Object> detail(String id,String scope,Session user)throws Exception{return human(200,"GET","/api/work-requests/detail?id="+id+"&type=AGENT_UPDATE"+scope,null,user).json;}
    private static Map<String,Object> onlyMachine(Map<String,Object> detail){List<Object> machines=array(detail.get("machines"));check(machines.size()==1,"exactly one scoped machine");return obj(machines.get(0));}
    private static Map<String,Object> counts(Map<String,Object> detail){return obj(obj(detail.get("request")).get("counts"));}
    private static long count(Object value){return ((Number)value).longValue();}
    private static Map<String,Object> page(String query,Session user)throws Exception{return human(200,"GET","/api/work-requests"+query,null,user).json;}
    private static String batch(Map<String,Object> response){return (String)response.get("batchId");}
    private static String collect(Session admin,String host,String captured,List<Object> warnings)throws Exception{
        String id=(String)human(202,"POST","/api/jobs",map("hostId",host),admin).json.get("id");
        check(id.equals(agent(200,"GET","/api/agent/poll?hostId="+host,null,host).json.get("jobId")),"agent acquires actual collection lease");
        Map<String,Object> snapshot=map("schemaVersion","1.0","eventId",UUID.randomUUID().toString(),"jobId",id,"capturedAt",captured,"collectorJavaVersion","21.0.12","host",map("id",host,"hostname",host),"coverage",map("status",warnings.isEmpty()?"complete":"partial","warnings",warnings,"stats",map("fixtureSecret","PRIVATE_STATS_MUST_NOT_APPEAR")));
        for(String kind:List.of("runtimes","processes","servers","libraries","applications","datasources"))snapshot.put(kind,List.of());agent(200,"POST","/api/agent/results",snapshot,host);return id;
    }
    private static Map<String,Object> assessment(String id,Session user)throws Exception{return human(200,"GET","/api/work-requests/detail?id="+id+"&type=ASSESSMENT",null,user).json;}
