        var request=map("id",id,"batchId",batch,"hostId",host,"ordinal",0,"fromVersion",OLD,"targetVersion",DashboardVersion.VERSION,"status",state,"createdAt",at,"updatedAt",later,"updatedMillis",System.currentTimeMillis(),"expiresMillis",System.currentTimeMillis()+600000,"claimedMillis",System.currentTimeMillis(),"diagnostic",state.equals("UNCONFIRMED")?"NETWORK_UNCONFIRMED":"","actorName","Fixture Admin");
        request.put("environmentId",app.store.get("hosts",host).get("environmentId"));
